import re

def calc(expr: str) -> int:
    # Remove all whitespace
    expr = expr.replace(" ", "")

    # Tokenize the expression
    # Tokens: numbers, operators (+, -, *, /, ^, (, )), and unary minus indicator
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            num = ""
            while i < len(expr) and expr[i].isdigit():
                num += expr[i]
                i += 1
            tokens.append(int(num))
            continue
        else:
            tokens.append(expr[i])
            i += 1

    # Handle unary minus by transforming it into a special token or 
    # by inserting a 0 before it to treat it as 0 - x.
    # However, to respect precedence (-2^2 = -4), we treat unary minus 
    # as a high-precedence operator.

    # Shunting-yard algorithm to convert to Reverse Polish Notation (RPN)
    # Precedence:
    # ^ : 4 (Right associative)
    # unary - : 3 (Right associative)
    # * / : 2 (Left associative)
    # + - : 1 (Left associative)

    precedence = {'^': 4, 'u-': 3, '*': 2, '/': 2, '+': 1, '-': 1}
    associativity = {'^': 'R', 'u-': 'R', '*': 'L', '/': 'L', '+': 'L', '-': 'L'}

    output = []
    stack = []

    # To distinguish unary minus from binary minus:
    # A minus is unary if it's at the start or follows an operator or '('
    for idx, token in enumerate(tokens):
        if isinstance(token, int):
            output.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop() # remove '('
        else:
            # Check if '-' is unary
            op = token
            if op == '-':
                if idx == 0 or tokens[idx-1] in '+-*/^(':
                    op = 'u-'

            while stack and stack[-1] != '(':
                top = stack[-1]
                if (associativity[op] == 'L' and precedence[op] <= precedence[top]) or \
                   (associativity[op] == 'R' and precedence[op] < precedence[top]):
                    output.append(stack.pop())
                else:
                    break
            stack.append(op)

    while stack:
        output.append(stack.pop())

    # Evaluate RPN
    eval_stack = []
    for token in output:
        if isinstance(token, int):
            eval_stack.append(token)
        elif token == 'u-':
            val = eval_stack.pop()
            eval_stack.append(-val)
        else:
            b = eval_stack.pop()
            a = eval_stack.pop()
            if token == '+': eval_stack.append(a + b)
            elif token == '-': eval_stack.append(a - b)
            elif token == '*': eval_stack.append(a * b)
            elif token == '/':
                # Integer division truncating toward zero
                res = abs(a) // abs(b)
                if (a < 0) ^ (b < 0):
                    res = -res
                eval_stack.append(res)
            elif token == '^':
                eval_stack.append(a ** b)

    return eval_stack[0]
