def int_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def helper(num: int) -> list:
        res = []
        if num >= 100:
            res.append(ones[num // 100])
            res.append("hundred")
            num %= 100

        if 10 <= num <= 19:
            res.append(teens[num - 10])
        elif num >= 20:
            res.append(tens[num // 10])
            if num % 10 > 0:
                res.append("-" + ones[num % 10])
        elif num > 0:
            res.append(ones[num])

        # Clean up hyphenated words from list to single string element
        # The logic above adds "-two" as a separate element, we need to join them.
        # However, to keep it simple, let's refine the logic to return a list of words.
        return res

    def process_chunk(num: int) -> list:
        if num == 0:
            return []

        words = []
        if num >= 100:
            words.append(ones[num // 100])
            words.append("hundred")
            num %= 100

        if num >= 10 and num <= 19:
            words.append(teens[num - 10])
        elif num >= 20:
            tens_part = tens[num // 10]
            if num % 10 > 0:
                words.append(f"{tens_part}-{ones[num % 10]}")
            else:
                words.append(tens_part)
        elif num > 0:
            words.append(ones[num])
        return words

    chunks = []
    # Million
    millions = n // 1000000
    if millions > 0:
        chunks.extend(process_chunk(millions))
        chunks.append("million")

    # Thousands
    thousands = (n % 1000000) // 1000
    if thousands > 0:
        chunks.extend(process_chunk(thousands))
        chunks.append("thousand")

    # Remainder
    remainder = n % 1000
    if remainder > 0:
        chunks.extend(process_chunk(remainder))

    return " ".join(chunks)
