def flatten_json(obj: dict) -> dict:
    def recurse(current, path):
        # If it's a dict and not empty, recurse into keys
        if isinstance(current, dict) and current:
            items = {}
            for k, v in current.items():
                new_path = f"{path}.{k}" if path else str(k)
                items.update(recurse(v, new_path))
            return items

        # If it's a list and not empty, recurse into indices
        elif isinstance(current, list) and current:
            items = {}
            for i, v in enumerate(current):
                new_path = f"{path}.{i}" if path else str(i)
                items.update(recurse(v, new_path))
            return items

        # Otherwise, it's a leaf (including empty dicts/lists)
        else:
            return {path: current}

    # Handle the edge case where the input itself is empty
    if not obj:
        return {}

    return recurse(obj, "")
