            regex_parts.append('.*')
            i += 1
        elif pattern[i] == '?':
            regex_parts.append('.')
            i += 1
        elif pattern[i] == '[':
            end = -1
            for k in range(i + 1, len(pattern)):
                if pattern[k] == ']':
                    end = k
                    break
            if end == -1:
                regex_parts.append(re.escape('['))
                i += 1
            else:
                inner = pattern[i+1:end]
                negated = False
                if inner.startswith('!'):
                    negated = True
                    inner = inner[1:]

                # re.escape handles characters like ']' and '^' correctly.
                # In Python 3.7+, it does not escape '-'.
                chars = "".join(re.escape(c) for c in inner)
                regex_parts.append(f'{"[^" if negated else "["}{chars}]')
                i = end + 1
        else:
            regex_parts.append(re.escape(pattern[i]))
            i += 1

    try:
        return bool(re.fullmatch("".join(regex_parts), name))
    except re.error:
        return False
